package cn.xinji.agentplatform.consultation.caselibrary.application;

import cn.xinji.agentplatform.consultation.application.ConsultationAuthorizationPort;
import cn.xinji.agentplatform.consultation.caselibrary.domain.CaseLibraryRecord;
import java.time.Clock;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;

@Service
public class CaseAnnotationWorkflowService {
    public static final String CONFIG="SYNTHETIC_EXTRACT_V1";
    private final CaseLibraryPort source; private final ConsultationAuthorizationPort authorization; private final Clock clock; private final CaseAnnotationWorkflowStore store;
    public CaseAnnotationWorkflowService(CaseLibraryPort source,ConsultationAuthorizationPort authorization,Clock clock,CaseAnnotationWorkflowStore store){this.source=source;this.authorization=authorization;this.clock=clock;this.store=store;}
    public Task extract(String actor,String caseId,String sourceVersion,String config,String requestId){access(actor,requestId);if(!CONFIG.equals(config))throw error("INVALID_CONFIG","仅支持固定合成提取配置",HttpStatus.BAD_REQUEST,requestId);CaseLibraryRecord record=source.find(caseId).orElseThrow(()->error("RECORD_NOT_FOUND","案例不存在",HttpStatus.NOT_FOUND,requestId));if(!record.sourceVersion().equals(sourceVersion))throw error("SOURCE_VERSION_CONFLICT","原文版本不一致",HttpStatus.CONFLICT,requestId);var doc=record.documents().getFirst();if(doc.paragraphs().size()<3)throw error("SOURCE_PARSE_FAILED","原文无足够可定位内容，不能提取",HttpStatus.UNPROCESSABLE_ENTITY,requestId);String annotationId="ANN-"+UUID.randomUUID();String now=now();Annotation a=new Annotation(annotationId,caseId,sourceVersion,1,"PENDING_REVIEW",doc.paragraphs().get(0).text(),doc.paragraphs().get(1).text(),doc.paragraphs().get(2).text(),doc.paragraphs().get(0).sourceLocation(),actor,"合成提取生成",now);Task task=new Task("TASK-"+UUID.randomUUID(),caseId,sourceVersion,config,"SUCCEEDED",1,annotationId,requestId,now);return store.createIfAbsent(actor,task,a,new Audit(annotationId,"EXTRACT",actor,"固定合成提取",1,now));}
    public Annotation revise(String actor,String id,int expected,String fact,String issue,String holding,String location,String reason,String requestId){access(actor,requestId);if(blank(reason)||blank(location))throw error("EVIDENCE_OR_REASON_REQUIRED","修订原因和证据位置必填",HttpStatus.BAD_REQUEST,requestId);Annotation old=current(id,requestId);version(old,expected,requestId);String now=now();Annotation next=new Annotation(id,old.caseId(),old.sourceVersion(),old.version()+1,"DRAFT",fact,issue,holding,location,actor,reason,now);return append(expected,next,new Audit(id,"REVISE",actor,reason,next.version(),now),requestId);}
    public Annotation submit(String actor,String id,int expected,String requestId){return transition(actor,id,expected,"PENDING_REVIEW","SUBMIT",null,requestId);}
    public Annotation review(String actor,String id,int expected,String action,String reason,String requestId){if("RETURN".equals(action)&&blank(reason))throw error("REASON_REQUIRED","退回理由必填",HttpStatus.BAD_REQUEST,requestId);String state=switch(action){case "PUBLISH"->"PUBLISHED";case "RETURN"->"RETURNED";default->throw error("INVALID_ACTION","审核动作无效",HttpStatus.BAD_REQUEST,requestId);};return transition(actor,id,expected,state,action,reason,requestId);}
    public Annotation withdraw(String actor,String id,int expected,String reason,String requestId){if(blank(reason))throw error("REASON_REQUIRED","撤回理由必填",HttpStatus.BAD_REQUEST,requestId);return transition(actor,id,expected,"WITHDRAWN","WITHDRAW",reason,requestId);}
    public Snapshot snapshot(String actor,String caseId,String requestId){access(actor,requestId);return new Snapshot("SYNTHETIC_V0",store.storageMode(),caseId,store.annotationsForCase(caseId),store.auditsForCase(caseId),requestId);}
    public Optional<Annotation> published(String caseId,String sourceVersion){return store.published(caseId,sourceVersion);}
    private Annotation transition(String actor,String id,int expected,String state,String action,String reason,String requestId){access(actor,requestId);Annotation old=current(id,requestId);version(old,expected,requestId);if((action.equals("PUBLISH")||action.equals("RETURN"))&&!old.state().equals("PENDING_REVIEW"))throw error("INVALID_TRANSITION","当前状态不可审核",HttpStatus.CONFLICT,requestId);String now=now();Annotation next=new Annotation(id,old.caseId(),old.sourceVersion(),old.version()+1,state,old.fact(),old.issue(),old.holding(),old.sourceLocation(),actor,reason,now);return append(expected,next,new Audit(id,action,actor,reason,next.version(),now),requestId);}
    private Annotation current(String id,String requestId){return store.current(id).orElseThrow(()->error("ANNOTATION_NOT_FOUND","标注不存在",HttpStatus.NOT_FOUND,requestId));}private static void version(Annotation a,int e,String id){if(a.version()!=e)throw error("VERSION_CONFLICT","标注版本冲突",HttpStatus.CONFLICT,id);}private Annotation append(int expected,Annotation next,Audit audit,String requestId){try{return store.append(expected,next,audit);}catch(CaseAnnotationWorkflowStore.VersionConflictException conflict){throw error("VERSION_CONFLICT","标注版本冲突",HttpStatus.CONFLICT,requestId);}}private void access(String a,String id){if(!authorization.maySearch(a))throw error("ACCESS_DENIED","当前身份无权操作案例标注",HttpStatus.FORBIDDEN,id);}private String now(){return clock.instant().toString();}private static boolean blank(String v){return v==null||v.isBlank();}private static WorkflowException error(String c,String m,HttpStatus s,String id){return new WorkflowException(c,m,s,id);}
    public record Task(String taskId,String caseId,String sourceVersion,String config,String status,int attempts,String annotationId,String requestId,String updatedAt){} public record Annotation(String annotationId,String caseId,String sourceVersion,int version,String state,String fact,String issue,String holding,String sourceLocation,String actor,String reason,String updatedAt){} public record Audit(String annotationId,String action,String actor,String reason,int annotationVersion,String createdAt){} public record Snapshot(String dataMode,String storageMode,String caseId,List<Annotation> annotations,List<Audit> audits,String requestId){}
    public static final class WorkflowException extends RuntimeException{private final String code;private final HttpStatus status;private final String requestId;WorkflowException(String c,String m,HttpStatus s,String r){super(m);code=c;status=s;requestId=r;}public String code(){return code;}public HttpStatus status(){return status;}public String requestId(){return requestId;}}
}
